}
const resolved=[...new Set(namesAll.filter(Boolean))];
return [{ json:{ map, resolved, __health:{ node:'csl-enrich-mcat', ok: (typeof ids==="undefined"||!ids||!ids.length) ? true : (typeof rows!=="undefined"&&Array.isArray(rows)&&rows.length>0) /* v42 honest ok: false when IDs were requested but Redash returned no names (outage/silent loss) */, requested:ids.length, resolved:resolved.length } } }];

// NODE: gst-resolve — aggregate ALL gst-fetch output items (one per contact: mobile or email),
// pull EVERY GSTIN each response returned, keep only well-formed GSTINs, DEDUPE (Set, upper-cased),
// and emit the deduped LIST. API success shape: { status, result:[ ...GSTINs... ] } where result may
// hold one OR MANY GSTINs. Defensive about where the body lives (.json, .json.result, .json.body.result, ...).
const items = $input.all();

// Full-string GSTIN format (case-insensitive); we upper-case before dedup.
const GSTIN_FULL = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]$/i;
const GSTIN_FIND = /\b[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]\b/i;

function pickResultArray(body) {
  if (!body || typeof body !== 'object') return null;
  if (Array.isArray(body.result)) return body.result;
  if (Array.isArray(body.results)) return body.results;
  if (body.data && Array.isArray(body.data.result)) return body.data.result;
  if (Array.isArray(body.data)) return body.data;
  if (body.body && Array.isArray(body.body.result)) return body.body.result;
  return null;
}
// Pull EVERY candidate GSTIN string out of one result element (string or object).
function gstinsFrom(el) {
  const out = [];
  const consider = s => {
    if (typeof s !== 'string') return;
    const t = s.trim();
    if (GSTIN_FULL.test(t)) { out.push(t); return; }
    const m = t.match(GSTIN_FIND); if (m) out.push(m[0]);
  };
  if (typeof el === 'string') { consider(el); }
  else if (el && typeof el === 'object') {
    for (const k of ['gstin', 'gst', 'gstNo', 'gst_no', 'GSTIN', 'gstin_no', 'value']) consider(el[k]);
  }
  return out;
}
function statusOf(body) {
  if (!body || typeof body !== 'object') return null;
  if (body.status != null) return body.status;
  if (body.data && body.data.status != null) return body.data.status;
  if (body.body && body.body.status != null) return body.body.status;
  return null;
}

const seen = new Set();
const gsts = [];        // deduped, upper-cased
const per = [];         // { gstin, via_contact, via_type }
let contacts_tried = 0;

for (const it of items) {
  const j = (it && it.json != null) ? it.json : it;
  if (!j) continue;
  // skip the no-contact sentinel from gst-compile-contacts
  if (j.skip === true && (j.contact == null || j.contact === '')) continue;
  if (j.ctype === 'none') continue;
  contacts_tried++;
  // body can be at j (responseFormat json), j.body, j.data, j.json, or nested .body.result
  const body = (j.result != null || j.status != null) ? j
             : (j.body != null) ? j.body
             : (j.data != null && (j.data.result != null || j.data.status != null)) ? j.data
             : (j.json != null) ? j.json
             : j;
  const arr = pickResultArray(body);
  if (!Array.isArray(arr)) continue;
  for (const el of arr) {
    for (const g of gstinsFrom(el)) {
      const up = g.toUpperCase();
      if (!seen.has(up)) {
        seen.add(up);
        gsts.push(up);
        per.push({ gstin: up, via_contact: (j.contact != null ? j.contact : ''), via_type: (j.ctype != null ? j.ctype : '') });
      }
    }
  }
}

return [{ json: {
  gsts: gsts,
  gst: gsts[0] || '',
  gst_count: gsts.length,
  gst_found: gsts.length > 0,
  contacts_tried: contacts_tried,
  per: per
} }];

// NODE: gst-compile-contacts — collect ALL valid buyer CONTACTS (mobiles AND emails) across
// anchor_extract / identity / external, dedupe per type, and emit ONE OUTPUT ITEM PER CONTACT
// tagged with ctype ('mobile'|'email') so the downstream gst-fetch HTTP node runs once per contact
// and routes URL+body by ctype. Reads upstream nodes by name (all already executed).
// Defensive: each $() lookup in its own try/catch.
const last10 = v => String(v == null ? '' : v).replace(/\D/g, '').slice(-10);
const isEmail = v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v == null ? '' : v).trim());

const seenMob = new Set();
const seenEm  = new Set();
const contacts = [];  // { contact, ctype }
const addMobile = v => { const m = last10(v); if (m && m.length === 10 && !seenMob.has(m)) { seenMob.add(m); contacts.push({ contact: m, ctype: 'mobile' }); } };
const addEmail  = v => { if (!isEmail(v)) return; const e = String(v).trim().toLowerCase(); if (!seenEm.has(e)) { seenEm.add(e); contacts.push({ contact: e, ctype: 'email' }); } };

// 1) anchor_extract — primary anchor mobile + email (json.anchors.{mobile,email}; tolerate flat json.{mobile,email})
try {
  const a = $('anchor_extract').first().json;
  if (a) {
    add_mobiles: { addMobile(a.mobile); if (a.anchors) addMobile(a.anchors.mobile); }
    add_emails:  { addEmail(a.email);  if (a.anchors) addEmail(a.anchors.email); }
  }
} catch (e) {}

// 2) identity — BL profile multi-mobile + multi-email arrays (json.summary.{mobiles,emails}[]; tolerate flat)
try {
  const id = $('identity').first().json;
  const mArr = (id && id.summary && Array.isArray(id.summary.mobiles)) ? id.summary.mobiles
             : (id && Array.isArray(id.mobiles)) ? id.mobiles : [];
  for (const m of mArr) addMobile(m);
  const eArr = (id && id.summary && Array.isArray(id.summary.emails)) ? id.summary.emails
             : (id && Array.isArray(id.emails)) ? id.emails : [];
  for (const e of eArr) addEmail(e);
} catch (e) {}

// 3) external — befisc alternate phone (json.summary.mobile) + befisc email (json.summary.email); tolerate other shapes
try {
  const ex = $('external').first().json;
  if (ex) {
    if (ex.summary) {
      addMobile(ex.summary.mobile);
      if (Array.isArray(ex.summary.mobiles)) for (const m of ex.summary.mobiles) addMobile(m);
      addEmail(ex.summary.email);
      if (Array.isArray(ex.summary.emails)) for (const e of ex.summary.emails) addEmail(e);
    }
    addMobile(ex.mobile);
    addEmail(ex.email);
    try { const bf = ex.raw && ex.raw.befisc && ex.raw.befisc.result; const ap = bf && bf.alternate_phone; if (Array.isArray(ap)) for (const x of ap) addMobile(x && x.value ? x.value : x); } catch (e2) {}
  }
} catch (e) {}

try { const _bpc = $('bp-parse').first().json; const _s = _bpc && _bpc.summary; if (_s) { (Array.isArray(_s.mobiles) ? _s.mobiles : []).forEach(addMobile); (Array.isArray(_s.emails) ? _s.emails : []).forEach(addEmail); } } catch (e) {}
if (!contacts.length) {
  return [{ json: { contact: '', ctype: 'none', skip: true } }];
}
return contacts.map(c => ({ json: { contact: c.contact, ctype: c.ctype } }));

// ===== NODE: external (Befisc + Sign3 trust, one node) =====
// run-once-for-all-items. Reads befisc-fetch + sign3-fetch raw API responses,
// reuses v9.5 befisc-parser + sign3-parser logic VERBATIM, emits one trust summary.

// ---- shared helpers (verbatim from v9.5 parsers) ----
const dec = s => { try { return decodeURIComponent(String(s).replace(/\+/g,' ')); } catch(e){ return String(s); } };
const isEmpty = v => v==null||v===''||v==='-'||v==='0'||v===0;
const titleCase = s => String(s).trim().toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());
const slugName = s => dec(s).replace(/\.html?$/i,'').replace(/-\d{6,}$/,'').replace(/-/g,' ').trim();
const mode = obj => Object.keys(obj).sort((a,b)=>obj[b]-obj[a])[0]||null;
const dedupeCI = arr => { const m=new Map(); for(const x of arr){ const k=String(x).toLowerCase().trim(); if(k&&!m.has(k)) m.set(k,x); } return [...m.values()]; };
const cleanUrl = u => { if(typeof u!=='string') return ''; const m=u.match(/^(?:GET|POST|PUT|DELETE|HEAD|PATCH)?\s*(\S+)/); return (m?m[1]:u).split(' HTTP')[0]; };
const qp = (url,key)=>{ const i=url.indexOf('?'); if(i<0) return null; const w=key.toLowerCase(); for(const kv of url.slice(i+1).split('&')){const eq=kv.indexOf('='); if(eq>0&&kv.slice(0,eq).toLowerCase()===w) return dec(kv.slice(eq+1));} return null; };
function omitEmpty(o){ const out={}; for(const k in o){ const v=o[k]; if(v==null||v==='') continue; if(Array.isArray(v)){ if(v.length) out[k]=v; continue;} if(typeof v==='object'){ const c=omitEmpty(v); if(Object.keys(c).length) out[k]=c; continue;} out[k]=v; } return out; }
function fixNull(o){ const out={}; for(const k in o){ out[k] = o[k]===undefined ? null : o[k]; } return out; }

// ---- befisc-parser logic (VERBATIM from v9.5 befisc-parser) ----
function parseBefisc(input){
  if(!input||input.error) return fixNull({ observed_only:true, status:'unavailable', error: input&&input.error&&input.error.message });
  const r=(input.result)||{}; const pi=r.personal_information||{}; const firstVal=a=>(Array.isArray(a)&&a[0])?(a[0].value||a[0]):null; const addr=(Array.isArray(r.address)&&r.address[0])||{};
  return fixNull({ observed_only:true, status: input.message||(input.status===1?'found':'unknown'), full_name: pi.full_name, gender: pi.gender, age: pi.age, date_of_birth: pi.date_of_birth, income_band: pi.income, pan: (r.document_data&&Array.isArray(r.document_data.pan))?firstVal(r.document_data.pan):null, home_address: addr.detailed_address?String(addr.detailed_address).replace(/\s+/g,' ').trim():null, address_city: addr.city||null, pincode: addr.pincode, address_state: addr.state, alternate_phone: firstVal(r.alternate_phone), email: firstVal(r.email) });
}

// ---- sign3-parser logic (VERBATIM from v9.5 sign3-parser) ----
function parseSign3(input){
  if(!input||input.error){ return fixNull({ observed_only:true, status:'unavailable', error: input&&input.error&&input.error.message }); }
  const pd=(input&&input.phone_data)||{}; const pr=pd.primary_data||{}; const li=pd.linked_data||{};
  const intel=pd.intelligence_data||{};
  const present=o=>Object.keys(o||{}).filter(k=>o[k]&&o[k].user_exist);
  // borrowed from intern sign3_parser: associated_names[0] (name + confidence) under phone_data.intelligence_data
  const assoc0=(Array.isArray(intel.associated_names)&&intel.associated_names[0])||null;
  return fixNull({ observed_only:true, status:'ok',
    bank_verified_name: intel.bank_verified_name,
    assoc_name: assoc0&&assoc0.name, assoc_name_confidence: assoc0&&assoc0.confidence_score,
    phone_operator: pr.phone_meta&&pr.phone_meta.operator, phone_circle: pr.phone_meta&&pr.phone_meta.circle,
    phone_social_count: pr.social_profile_count, phone_accounts: present(pr.account_details),
    email_social_count: li.social_profile_count, email_accounts: present(li.account_details),
    google_maps_reviews: li.account_details&&li.account_details.GOOGLE&&li.account_details.GOOGLE.reviews,
    google_maps: (function(){ var g = li.account_details && li.account_details.GOOGLE; if(!g || !(g.maps_data_found || g.maps_url || g.name)) return null; return { name: g.name||null, url: g.maps_url||null, level: (g.level!=null?g.level:null), points: (g.points!=null?g.points:null), reviews: (g.reviews!=null?g.reviews:null), ratings: (g.ratings!=null?g.ratings:null), photos: (g.photos!=null?g.photos:null) }; })(),
    phone_breaches:((pr.breach_details&&pr.breach_details.breaches)||[]).map(b=>b.name),
    email_breaches:((li.breach_details&&li.breach_details.breaches)||[]).map(b=>b.name),
  });
}

// ---- merge: ONE trust summary (PII dropped, never to LLM) ----
const INCOME_PLACEHOLDERS = new Set(['insufficient updates','inactive']);
function cleanIncome(v){
  if(v==null||v==='') return null;
  if(INCOME_PLACEHOLDERS.has(String(v).trim().toLowerCase())) return null;
  return v;
}
const norm = s => String(s||'').toLowerCase().replace(/\b(mr|mrs|ms|dr|m\/s|s\/o|d\/o|w\/o)\b/g,' ').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
function namesAgree(a,b){
  const na=norm(a), nb=norm(b); if(!na||!nb) return false;
  if(na===nb) return true;
  const ta=new Set(na.split(' ').filter(Boolean)), tb=nb.split(' ').filter(Boolean);
  if(!tb.length) return false;
  const overlap = tb.filter(t=>ta.has(t)).length;
  // agree if every token of the shorter set is contained, or strong overlap (>=2 shared tokens)
  return overlap>=2 || (overlap>0 && (overlap===tb.length || overlap===ta.size));
}

function run(befiscRaw, sign3Raw){
  const __health = { node:'external', ok:true, befisc_input:false, sign3_input:false };

  let befisc = { observed_only:true, status:'unavailable' };
  try { if(befiscRaw!=null){ __health.befisc_input=true; befisc = parseBefisc(befiscRaw); } }
  catch(e){ befisc = { observed_only:true, status:'unavailable', error:String(e&&e.message||e) }; __health.befisc_error=String(e&&e.message||e); }

  let sign3 = { observed_only:true, status:'unavailable' };
  try { if(sign3Raw!=null){ __health.sign3_input=true; sign3 = parseSign3(sign3Raw); } }
  catch(e){ sign3 = { observed_only:true, status:'unavailable', error:String(e&&e.message||e) }; __health.sign3_error=String(e&&e.message||e); }

  // record-found flags
  const befisc_found = !!(befiscRaw && (befiscRaw.status===1 || befisc.status==='found'));
  const sign3_found  = !!(sign3Raw && sign3Raw.phone_data && (String(sign3Raw.status||'').toUpperCase()==='SUCCESS' || sign3.status==='ok'));

  const bankName  = (sign3.bank_verified_name && String(sign3.bank_verified_name).trim()) || null;
  const befiscName = (befisc.full_name && String(befisc.full_name).trim()) || null;
  // borrowed: sign3 associated_names[0] (name as bank fallback, confidence as a trust signal)
  const assocName = (sign3.assoc_name && String(sign3.assoc_name).trim()) || null;
  const verified_name_confidence = sign3.assoc_name_confidence || null;

  // verified_name: sign3 bank_verified_name ∪ sign3 associated-name ∪ befisc full_name (sign3 bank preferred — bank-grade)
  let verified_name = null, verified_name_source = null;
  if(bankName){ verified_name = bankName; verified_name_source = 'sign3_bank'; }
  else if(assocName){ verified_name = assocName; verified_name_source = 'sign3_associated'; }
  else if(befiscName){ verified_name = befiscName; verified_name_source = 'befisc'; }

  const name_cross_source_match = !!(bankName && befiscName) ? namesAgree(bankName, befiscName) : null;

  const income_band = cleanIncome(befisc.income_band);

  // social presence: prefer phone count, fall back to email count.
  // social_platforms: the platform name list from the SAME source as the count (keep count too).
  let social_presence_count = null, social_platforms = [];
  if(typeof sign3.phone_social_count === 'number'){
    social_presence_count = sign3.phone_social_count;
    social_platforms = Array.isArray(sign3.phone_accounts) ? sign3.phone_accounts : [];
  } else if(typeof sign3.email_social_count === 'number'){
    social_presence_count = sign3.email_social_count;
    social_platforms = Array.isArray(sign3.email_accounts) ? sign3.email_accounts : [];
  }

  const identity_verified = !!(bankName || befisc_found);
  const emailVal = (befisc.email && String(befisc.email).trim()) || null;

  // V10 (owner): this is a TRIANGULATION node, NOT a trim. KEEP the verifying PII — name/email/mobile/PAN/gender/
  // age/address(city,state)/income are the FUEL the LLM cross-checks against Profile + PNS + CSL for identity
  // confidence, persona, location triangulation and purchasing power. We drop ONLY genuine non-signal noise
  // (breach lists, social-account platform enumeration, serial numbers, API transport). phone_circle is kept but
  // LABELED telecom_sim_circle — it's where the SIM was issued, a weak secondary hint, NOT the buyer's location.
  const summary = {
    observed_only: true,
    // ── identity (for cross-source match vs Profile.name/email/mobile downstream) ──
    verified_name, verified_name_source,
    verified_name_confidence,                 // borrowed: sign3 associated_names[0].confidence_score
    befisc_name: befiscName || null,
    sign3_bank_name: bankName || null,
    sign3_associated_name: assocName || null, // borrowed: associated_names[0].name (used as verified_name fallback)
    name_cross_source_match,                  // befisc ↔ sign3 (profile↔external match is done by the LLM)
    email: emailVal,
    mobile: (befisc.alternate_phone && String(befisc.alternate_phone).trim()) || null,
    pan: befisc.pan || null,                  // identity verification — "PAN on file ✓"
    // ── persona ──
    gender: befisc.gender || null,
    age: befisc.age || null,
    date_of_birth: befisc.date_of_birth || null,
    // ── location triangulation (cross-check vs PNS-stated / Profile / CSL city) ──
    location: { city: befisc.address_city || null, state: befisc.address_state || null, pincode: befisc.pincode || null, full_address: befisc.home_address || null },
    // ── purchasing power + trust ──
    income_band,
    social_presence_count,
    social_platforms,                         // borrowed: platform name list (same source as the count)
    telecom_sim_circle: sign3.phone_circle || null,   // NOT location — SIM issue circle
    identity_verified,
    // Sign3 email-linked Google-Maps contributor profile (name . maps URL . level/points/reviews/ratings) — a real
    // digital-footprint signal the external node was reading but dropping (#12). Surfaced for the LLM + the card.
    google_business: sign3.google_maps || null,
    befisc_record_found: befisc_found,
    sign3_record_found: sign3_found,
  };

  // raw kept for debug/lineage
  const raw = { befisc: befiscRaw==null?null:befiscRaw, sign3: sign3Raw==null?null:sign3Raw };

  return { summary, raw, __health };
}

// ---- n8n entry: discriminate the two upstream inputs by content shape ----
const tolerantRoot = x => Array.isArray(x) ? x[0] : x;
let befiscRaw = null, sign3Raw = null;
try {
  // Prefer explicit node-by-name reads (robust to connection order)
  try { const b = $('befisc-fetch').first(); if(b && b.json!=null) befiscRaw = tolerantRoot(b.json); } catch(e){}
  try { const s = $('sign3-fetch').first(); if(s && s.json!=null) sign3Raw = tolerantRoot(s.json); } catch(e){}

  // Fallback / supplement: discriminate every connected input by its shape (the intern's pattern)
  let items = [];
  try { items = $input.all() || []; } catch(e){ items = []; }
  for(const it of items){
    const j = tolerantRoot(it && it.json);
    if(j==null || typeof j!=='object') continue;
    const looksSign3 = ('phone_data' in j) || ('request_id' in j) || (j.error && befiscRaw && !sign3Raw);
    const looksBefisc = ('result' in j && j.result && 'personal_information' in (j.result||{})) || ('api_category' in j) || ('txn_id' in j);
    if(looksBefisc && befiscRaw==null) befiscRaw = j;
    else if(looksSign3 && sign3Raw==null) sign3Raw = j;
  }
} catch(e){
  return [{ json: { summary:{ observed_only:true }, raw:{}, __health: { fetched_at: new Date().toISOString(), node:'external', ok:false, error:String(e&&e.message||e) } } }];
}

const out = run(befiscRaw, sign3Raw);
return [{ json: out }];

// NODE: "identity" — BL profile (registered identity) + GLUSR tenure (usersince), 1:1 merge on glid.
// Run-once-for-all-items. Reuses v9.5 parseProfile + parseUsersince VERBATIM, then composes the merge.
// Inputs: connected from BOTH "BL profile" and "usersince". Discriminated by content shape OR by node name.
// Output: ONE item [{ json:{ summary:{...}, raw:{...}, __health: { fetched_at: new Date().toISOString(),...} } }].

// ---- v9.5 shared helpers (lifted verbatim from profile-parser / usersince-parser) ----
const dec = s => { try { return decodeURIComponent(String(s).replace(/\+/g,' ')); } catch(e){ return String(s); } };
const isEmpty = v => v==null||v===''||v==='-'||v==='0'||v===0;
const titleCase = s => String(s).trim().toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());
const slugName = s => dec(s).replace(/\.html?$/i,'').replace(/-\d{6,}$/,'').replace(/-/g,' ').trim();
const mode = obj => Object.keys(obj).sort((a,b)=>obj[b]-obj[a])[0]||null;
const dedupeCI = arr => { const m=new Map(); for(const x of arr){ const k=String(x).toLowerCase().trim(); if(k&&!m.has(k)) m.set(k,x); } return [...m.values()]; };
const cleanUrl = u => { if(typeof u!=='string') return ''; const m=u.match(/^(?:GET|POST|PUT|DELETE|HEAD|PATCH)?\s*(\S+)/); return (m?m[1]:u).split(' HTTP')[0]; };
const qp = (url,key)=>{ const i=url.indexOf('?'); if(i<0) return null; const w=key.toLowerCase(); for(const kv of url.slice(i+1).split('&')){const eq=kv.indexOf('='); if(eq>0&&kv.slice(0,eq).toLowerCase()===w) return dec(kv.slice(eq+1));} return null; };
function omitEmpty(o){ const out={}; for(const k in o){ const v=o[k]; if(v==null||v==='') continue; if(Array.isArray(v)){ if(v.length) out[k]=v; continue;} if(typeof v==='object'){ const c=omitEmpty(v); if(Object.keys(c).length) out[k]=c; continue;} out[k]=v; } return out; }
function fixNull(o){ const out={}; for(const k in o){ out[k] = o[k]===undefined ? null : o[k]; } return out; }

// ---- borrowed-field helpers (from intern "BL_profile_extractor") ----
// emails: email1-4, drop blanks, dedupe (case-insensitive, order-preserving)
function collectEmails(p){
  const raw=[p.email1,p.email2,p.email3,p.email4].filter(v=>v&&String(v).trim());
  return dedupeCI(raw.map(v=>String(v).trim()));
}
// mobiles: mobile1-4 + ph_mobile + ph_mobile_alt, normalize to last-10 digits, dedupe order-preserving
function collectMobiles(p){
  const raw=[p.mobile1,p.mobile2,p.mobile3,p.mobile4,p.glusr_usr_ph_mobile,p.glusr_usr_ph_mobile_alt];
  const norm=raw.filter(v=>v&&String(v).trim())
                .map(v=>String(v).replace(/\D/g,'').slice(-10))
                .filter(v=>v);
  return norm.filter((v,i,arr)=>arr.indexOf(v)===i);
}

// ---- v9.5 parseProfile (lifted VERBATIM from "profile-parser") ----
function parseProfile(input){
  const p=input||{};
  return fixNull({
    name:[p.first_name,p.last_name].filter(Boolean).join(' ').trim()||p.first_name,
    company:p.company_name, designation:p.designation, city:p.city, district:p.glusr_usr_district, state:p.state, zip:p.zip,
    mobile:p.glusr_usr_ph_mobile, mobile_alt:p.glusr_usr_ph_mobile_alt, email:p.email1,
    is_paid:p.is_paid, listing_status:p.glusr_usr_listing_status, company_desc:p.glusr_usr_company_desc, website:p.website,
  });
}

// ---- v9.5 parseUsersince (lifted VERBATIM from "usersince-parser") ----
function parseUsersince(input){
  const g=(input&&input.glusr_extra)||{}; const since=g.glusr_usr_membersince; let ty;
  if(since){ const y=new Date(since); if(!isNaN(y)) ty=Math.round((Date.now()-y.getTime())/(365.25*864e5)*10)/10; }
  return fixNull({ member_since:since, tenure_years:ty, last_login:g.glusr_usr_lastlogin, last_modified:g.glusr_usr_lastmodified, listing_status:g.glusr_usr_listing_status, updated_by:g.glusr_usr_updatedby, updated_using:g.glusr_usr_updatedusing });
}

// ---- entry tolerance: array-or-object, and unwrap n8n {json:...} ----
const root = x => { const v = Array.isArray(x) ? x[0] : x; return (v && typeof v==='object' && v.json && typeof v.json==='object') ? v.json : v; };
const isProfileShape = o => !!(o && typeof o==='object' && ('first_name' in o || 'company_name' in o || 'glusr_usr_listing_status' in o || 'verified_business_buyer_flag' in o));
const isUsersinceShape = o => !!(o && typeof o==='object' && ('glusr_extra' in o));

// merge = registered-identity fields + OVERLAY tenure; explicit KEEP whitelist (REJECT plumbing dropped by omission)
function mergeIdentity(profRaw, usRaw){
  const prof = parseProfile(profRaw);            // registered identity
  const tenure = parseUsersince(usRaw);          // GLUSR tenure overlay
  const pRoot = profRaw || {};
  const emails = collectEmails(pRoot);           // borrowed: multi-email (deduped)
  const mobiles = collectMobiles(pRoot);         // borrowed: multi-mobile (last-10 deduped)
  const ceoName = [pRoot.ceo_fname, pRoot.ceo_lname].filter(Boolean).join(' ').trim() || null;
  const summary = {
    // registered identity (BL profile)
    name: prof.name,
    company: prof.company,
    designation: prof.designation,
    ceo_name: ceoName,                                                          // borrowed: segmentation
    city: prof.city,
    district: prof.district,
    state: prof.state,
    location_preference: (pRoot.location_preference===undefined ? null : pRoot.location_preference), // borrowed
    verified_business_buyer_flag: (pRoot.verified_business_buyer_flag===undefined ? null : pRoot.verified_business_buyer_flag),
    fcp_flag: (pRoot.fcp_flag===undefined ? null : pRoot.fcp_flag),             // borrowed: segmentation
    is_paid: prof.is_paid,
    paidurl: (pRoot.paidurl===undefined ? null : pRoot.paidurl),               // borrowed: monetization
    glusr_usr_approv: (pRoot.glusr_usr_approv===undefined ? null : pRoot.glusr_usr_approv), // borrowed: approval state
    // custtype segmentation triad (id/name/weight) — borrowed
    glusr_usr_custtype_id: (pRoot.glusr_usr_custtype_id===undefined ? null : pRoot.glusr_usr_custtype_id),
    glusr_usr_custtype_name: (pRoot.glusr_usr_custtype_name===undefined ? null : pRoot.glusr_usr_custtype_name),
    glusr_usr_custtype_weight: (pRoot.glusr_usr_custtype_weight===undefined ? null : pRoot.glusr_usr_custtype_weight),
    // multi-contact (borrowed, deduped/normalized)
    emails: emails,
    mobiles: mobiles,
    // listing_status: tenure (GLUSR system-of-record) overlays profile, profile as fallback
    listing_status: (tenure.listing_status!=null ? tenure.listing_status : prof.listing_status),
    // GLUSR tenure overlay
    member_since: tenure.member_since,
    tenure_years: tenure.tenure_years,
    last_login: tenure.last_login,
    last_modified: tenure.last_modified,
  };
  return fixNull(summary);
}

let summary = {}, rawOut = {}, ok = false, err = null;
let sawProfile = false, sawUsersince = false;
try {
  let profRaw = null, usRaw = null;

  // Prefer explicit node-by-name reads (intern's robust pattern), fall back to shape discrimination of $input.all().
  try { const bp = $('BL profile').first(); if (bp && bp.json!=null) profRaw = root(bp.json); } catch(e){}
  try { const us = $('usersince').first(); if (us && us.json!=null) usRaw = root(us.json); } catch(e){}

  if (profRaw==null || usRaw==null) {
    const all = $input.all() || [];
    for (const it of all) {
      const j = root(it && it.json!=null ? it.json : it);
      if (profRaw==null && isProfileShape(j)) profRaw = j;
      else if (usRaw==null && isUsersinceShape(j)) usRaw = j;
    }
  }

  sawProfile = !!(profRaw && typeof profRaw==='object');
  sawUsersince = !!(usRaw && typeof usRaw==='object');

  summary = mergeIdentity(profRaw, usRaw);
  rawOut = { profile: (profRaw||null), usersince: (usRaw||null) };
  ok = !!(summary && (summary.name!=null || summary.company!=null || summary.member_since!=null));
} catch (e) {
  err = String(e && e.message ? e.message : e);
  ok = false;
}

return [{ json: {
  summary,
  raw: rawOut,
  __health: { node:'identity', ok, saw_profile:sawProfile, saw_usersince:sawUsersince, error:err }
} }];

// ===== NODE: whatsapp (inbound ⊕ outbound → ONE timeline) =====
// Reuses v9.5 wa-conv-parser (parseWAconv) + wa-inbound-parser (parseWAinbound) VERBATIM,
// then composes a single sender-classified turn[] timeline.

// ---- shared helpers (verbatim from v9.5 wa-conv-parser / wa-inbound-parser) ----
const dec = s => { try { return decodeURIComponent(String(s).replace(/\+/g,' ')); } catch(e){ return String(s); } };
const isEmpty = v => v==null||v===''||v==='-'||v==='0'||v===0;
const titleCase = s => String(s).trim().toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());
const slugName = s => dec(s).replace(/\.html?$/i,'').replace(/-\d{6,}$/,'').replace(/-/g,' ').trim();
const mode = obj => Object.keys(obj).sort((a,b)=>obj[b]-obj[a])[0]||null;
const dedupeCI = arr => { const m=new Map(); for(const x of arr){ const k=String(x).toLowerCase().trim(); if(k&&!m.has(k)) m.set(k,x); } return [...m.values()]; };
const cleanUrl = u => { if(typeof u!=='string') return ''; const m=u.match(/^(?:GET|POST|PUT|DELETE|HEAD|PATCH)?\s*(\S+)/); return (m?m[1]:u).split(' HTTP')[0]; };
const qp = (url,key)=>{ const i=url.indexOf('?'); if(i<0) return null; const w=key.toLowerCase(); for(const kv of url.slice(i+1).split('&')){const eq=kv.indexOf('='); if(eq>0&&kv.slice(0,eq).toLowerCase()===w) return dec(kv.slice(eq+1));} return null; };
function omitEmpty(o){ const out={}; for(const k in o){ const v=o[k]; if(v==null||v==='') continue; if(Array.isArray(v)){ if(v.length) out[k]=v; continue;} if(typeof v==='object'){ const c=omitEmpty(v); if(Object.keys(c).length) out[k]=c; continue;} out[k]=v; } return out; }
function fixNull(o){ const out={}; for(const k in o){ out[k] = o[k]===undefined ? null : o[k]; } return out; }

// ---- parseWAconv: VERBATIM from v9.5 wa-conv-parser ----
function parseWAconv(input){
  const recs=(input&&input.data&&input.data.records)||[];
  const buyer=[]; const offered=new Set();
  for(const r of recs){ let d={}; try{ d=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){}
    if(r.eto_lead_attribute==='USER'){ const t=d.text||d.title; if(t) buyer.push(fixNull({date:r.insert_date,text:t})); }
    else { const cap=d.caption||d.text||''; const m=cap.match(/Need \*([^*]+)\* in \*([^*]+)\*/)||cap.match(/sellers of \*([^*]+)\* in \*([^*]+)\*/); if(m) offered.add(`${m[1]} (${m[2]})`); }
  }
  const OBJ_RE=/high price|not satisfied|need more sellers|no response|located too far|product unavailable|too far|expensive|costly/i;
  const objections=dedupeCI(buyer.map(b=>b.text).filter(t=>t&&OBJ_RE.test(t)));
  const dissatisfaction_count=buyer.filter(b=>/not satisfied|👎/i.test(b.text||'')).length;
  const locPref=[]; for(const b of buyer){ const t=String(b.text||''); const m=t.match(/^([A-Z][a-z]{2,})\s+(?:btao|chahiye|wale|wala|me|mein)\b/i); if(m) locPref.push(m[1]); else if(/near me|located near|aas ?paas|\bpaas\b/i.test(t)) locPref.push('Near me'); }
  const reqs=[]; for(const r of recs){ if(r.eto_lead_attribute==='USER') continue; let dd={}; try{ dd=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){} const tx=dd.text||(dd.interactive&&dd.interactive.body&&dd.interactive.body.text)||''; const mm=String(tx).match(/requirement for (.+?) has been (?:received|sent)/i); if(mm) reqs.push(mm[1].trim()); }
  const sellers=[]; const seenS=new Set();
  for(const r of recs){ if(r.eto_lead_attribute==='USER') continue; let dd={}; try{ dd=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){}
    const body=String((dd.interactive&&dd.interactive.body&&dd.interactive.body.text)||dd.caption||dd.text||'');
    const rt=body.match(/⭐\s*([0-9.]+)\s*\(([0-9]+)\)/); const pr=body.match(/(?:₹|Rs\.?|INR)\s*([0-9,]+)/i);
    let m=body.match(/^\*?([A-Z][^\n*(]{2,50}?)\*?\s*\(([^)\n]+)\)/);
    let name=null, city=null;
    if(m){ name=m[1].trim(); city=m[2].trim(); } else { const m2=body.match(/^\*([^*\n]{2,50})\*/); if(m2 && pr) name=m2[1].trim(); }
    if(name){ const k=name.toLowerCase(); if(!seenS.has(k)){ seenS.add(k); sellers.push(fixNull({ name, city, rating: rt?parseFloat(rt[1]):undefined, reviews: rt?parseInt(rt[2],10):undefined, price: pr?('₹'+pr[1]):undefined })); } } }
  const price_points=dedupeCI(sellers.map(s=>s.price).filter(Boolean));
  return fixNull({ buyer_messages:buyer, products_offered:[...offered], objections, dissatisfaction_count, location_preference:dedupeCI(locPref), requirements_discussed:dedupeCI(reqs), sellers_shown:sellers, price_points, message_count:recs.length });
}

// ---- parseWAinbound: VERBATIM from v9.5 wa-inbound-parser ----
function parseWAinbound(input){
  const msgs=(input&&input.data&&input.data.recent_messages)||[];
  const enq=[], prodSet=[], sellerSet=[], citySet=[];
  for(const m of msgs){ const c=(m.content||'').replace(/\r/g,''); let product=null,seller=null,city=null,mm;
    if((mm=c.match(/requirement for\s+(.+?)\s+has been sent to\s+([^.\n]+?)\.?\s*$/im))){ product=mm[1].trim(); seller=mm[2].trim(); }
    else if((mm=c.match(/has been sent to\s+([^.\n]+?)\.?\s*$/im))){ seller=mm[1].trim(); }
    if(!product && (mm=c.match(/requirement for\s+(.+?)\s+has been (?:sent|received)/im))) product=mm[1].trim();
    if(!seller && (mm=c.match(/(?:connect with|spoke with|connected with)\s*\*?([^*\n?]+?)\*?\s*[?📞\n]/i))) seller=mm[1].trim();
    if(!seller && /📞|indiamart\.com|TrustSEAL|GST Verified/i.test(c) && (mm=c.match(/^\s*([A-Z][^\n(]{2,}?)\s*\(([^)\n]+)\)\s*$/m))){ seller=mm[1].trim(); city=mm[2].trim(); }
    if(product) prodSet.push(product);
    if(seller && seller.length<60) sellerSet.push(seller);
    if(city) citySet.push(city);
    if(product||seller) enq.push(fixNull({ date:m.timestamp, product, seller, seller_city:city }));
  }
  const typedEnq=[]; const locPref=[]; let posFb=0, negFb=0;
  for(const m of msgs){ if(m.sender!=='user') continue; const c=String(m.content||'').replace(/\r/g,'');
    const ne=c.match(/Need best price for\s+([^\n,]+?)(?:,\s*([0-9]+\s*Gsm))?(?:\n|$)/i); if(ne) typedEnq.push(fixNull({ product:ne[1].trim(), gsm:ne[2]?ne[2].trim():undefined }));
    if(/👍|yes,?\s*perfect/i.test(c)) posFb++;
    if(/👎|not satisfied/i.test(c)) negFb++;
    if(/located near me|near me|aas ?paas|\bpaas\b/i.test(c)) locPref.push('Near me'); }
  return fixNull({ enquiries:enq, products:dedupeCI(prodSet), sellers_shared:dedupeCI(sellerSet), seller_cities:dedupeCI(citySet), buyer_typed_enquiries:typedEnq, location_preference:dedupeCI(locPref), positive_feedback:posFb, negative_feedback:negFb, message_count:input&&input.data&&input.data.message_count });
}

// ====================== MERGE: ONE timeline ======================
const root = x => Array.isArray(x) ? (x[0]||{}) : (x||{});
const tsOf = s => { if(!s) return null; const str=String(s).trim(); const iso = /[zZ]|[+-]\d{2}:?\d{2}$/.test(str) ? str : str.replace(' ','T')+'Z'; const t=Date.parse(iso); return Number.isFinite(t)?t:null; };
const clip = (s,n=400) => { const t=String(s==null?'':s).replace(/\r/g,'').trim(); return t.length>n?t.slice(0,n):t; };

// NOISE we REJECT entirely (OTP/verification, footer/unsubscribe, code/status/handles)
const OTP_RE   = /\b(?:OTP|one[- ]time password|verification code|verify your|\d{4,8}\s+is your)\b/i;
const FOOTER_RE= /type ['"]?stop['"]? to unsubscribe|unsubscribe|you will not receive any further message/i;
// media/carousel/handle junk that sometimes lands in a text field
const HANDLE_RE= /header_handle|aW1hZ2|imimg\.com\/data5|AiSensy-file/i;

// our-side caption product/location extractor (context, kept lightly)
function ourCaptionMeta(text){
  const m = text.match(/Need \*([^*]+)\* in \*([^*]+)\*/) || text.match(/sellers of \*([^*]+)\* in \*([^*]+)\*/) || text.match(/\*([^*]+)\* ka \*([^*]+)\* mein best price/);
  return m ? { product: m[1].trim(), location: m[2].trim() } : null;
}

// ---- BORROWED (intern whatsapp_outbound_structuer): campaign-funnel KPIs ----
// API record with a YES-prompt = a campaign we sent; USER record = buyer responded.
// VERBATIM intern logic, hardened with try/catch + safe optional access.
function computeCampaignFunnel(convIn){
  const recs = (convIn && convIn.data && Array.isArray(convIn.data.records)) ? convIn.data.records : [];
  let campaigns_received=0, campaigns_responded=0, yes_responses=0, no_responses=0;
  for (const r of recs){
    let detail={}; try { detail = JSON.parse((r&&r.eto_lead_attribute_detail) || '{}'); } catch(e){ continue; }
    if (r && r.eto_lead_attribute === 'API'){
      let blob='';
      if (detail.caption) blob += ' ' + detail.caption;
      if (detail.text) blob += ' ' + detail.text;
      if (detail.interactive && detail.interactive.body && detail.interactive.body.text) blob += ' ' + detail.interactive.body.text;
      if (blob.includes('YES') || blob.includes('Yes') || blob.includes('Reply with YES')) campaigns_received++;
    }
    if (r && r.eto_lead_attribute === 'USER'){
      campaigns_responded++;
      const response = String(detail.text || '').trim().toLowerCase();
      if (response === 'yes') yes_responses++;
      if (response === 'no') no_responses++;
    }
  }
  let response_rate = 0;
  if (campaigns_received > 0){
    response_rate = Math.min(100, Math.round((yes_responses / Math.max(1, campaigns_received)) * 100)); // v38: YES-replies only
  }
  return { campaigns_received, campaigns_responded, response_rate, yes_responses, no_responses };
}

// ---- BORROWED (intern whatsapp_inbound_structurer): discrete inbound flags ----
// VERBATIM intern detection strings, hardened with safe content access.
function computeInboundFlags(inbIn){
  const msgs = (inbIn && inbIn.data && Array.isArray(inbIn.data.recent_messages)) ? inbIn.data.recent_messages : [];
  const has = (needle) => msgs.some(m => typeof (m&&m.content) === 'string' && m.content.includes(needle));
  const images_requested = has('Share photos');
  const supplier_feedback_given = has('Not Satisfied') || has('Seller helpful');
  const intentSet = new Set();
  for (const m of msgs){
    const text = String((m && m.content) || '').toLowerCase();
    if (text.includes('reselling'))    intentSet.add('reselling');
    if (text.includes('distribution')) intentSet.add('distribution');
    if (text.includes('wholesale'))    intentSet.add('wholesale');
  }
  return { images_requested, explicit_business_intent: [...intentSet], supplier_feedback_given };
}

function buildTimeline(convIn, inbIn){
  const turns = [];
  const products_offered = new Set();   // what WE pitched (context)
  const products_enquired = new Set();   // what BUYER asked for (signal)
  const button_taps = [];                // buyer button/quick-reply taps (signal)
  let rejected = 0;

  // ---------- OUTBOUND (whatsapp-conversations: records[]) ----------
  const recs = (convIn && convIn.data && convIn.data.records) || [];
  for (const r of recs){
    let d={}; try{ d=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){}
    const ts = tsOf(r.insert_date);
    const isBuyer = r.eto_lead_attribute === 'USER';

    if (isBuyer){
      // BUYER side of the outbound channel = quick-reply taps, ISQ-option taps, ISQ-flow submissions, free text
      // 1) WhatsApp Flow / ISQ-spec form submission (response_json) — high-value spec answer
      if (d.response_json){
        let rj={}; try{ rj=JSON.parse(d.response_json); }catch(e){}
        const parts=[];
        if(rj.PRODUCT_NAME) parts.push(rj.PRODUCT_NAME);
        if(rj.INPUT_RECEIVED) parts.push(rj.INPUT_RECEIVED + (rj.QUANTITY_UNIT?(' '+rj.QUANTITY_UNIT):''));
        else if(rj.QUANTITY_UNIT) parts.push(rj.QUANTITY_UNIT);
        if(rj.DISPOSITION) parts.push(rj.DISPOSITION);
        const text = clip(parts.filter(Boolean).join(' · ') || d.body || 'spec submitted');
        if(rj.PRODUCT_NAME) products_enquired.add(rj.PRODUCT_NAME.trim());
        turns.push({ ts, sender:'buyer', kind:'isq_answer', text, channel:'outbound' });
        continue;
      }
      // 2) explicit text or button title
      const raw = d.text || d.title || '';
      const text = clip(raw);
      if (!text){ rejected++; continue; }
      if (OTP_RE.test(text) || FOOTER_RE.test(text) || HANDLE_RE.test(text)){ rejected++; continue; }
      // a callbackPayload OR an `id`+`title` (ISQ option) means it's a tap, not free text
      const isTap = !!d.callbackPayload || (d.id!=null && d.title!=null) || /^(yes|no|stop|y|n)$/i.test(text);
      // ISQ-option taps carry a meaningful selected value as `title`
      const kind = d.callbackPayload && /^(yes|no|stop|y|n)$/i.test(text) ? 'button_tap'
                 : (d.title!=null && d.callbackPayload==null) ? 'isq_answer'
                 : isTap ? 'button_tap' : 'free_text';
      if (kind==='button_tap' || kind==='isq_answer') button_taps.push(text);
      turns.push({ ts, sender:'buyer', kind, text, channel:'outbound' });
    } else {
      // API = OURS (context). Keep caption/body text; reject pure media/carousel/footer noise.
      const body = String((d.interactive&&d.interactive.body&&d.interactive.body.text) || d.caption || d.text || '');
      const text = clip(body);
      if (text){
        const meta = ourCaptionMeta(text);
        if (meta && meta.product) products_offered.add(`${meta.product} (${meta.location})`);
      }
      // skip footer-only / handle-only / empty -> still a turn but flagged; reject if nothing usable
      if (!text || HANDLE_RE.test(text)){ rejected++; continue; }
      const isFooter = FOOTER_RE.test(text);
      turns.push({ ts, sender:'ours', kind: isFooter?'footer':'caption', text, channel:'outbound' });
    }
  }

  // ---------- INBOUND (whatsapp-inbound: recent_messages[]) ----------
  const msgs = (inbIn && inbIn.data && inbIn.data.recent_messages) || [];
  for (const m of msgs){
    const ts = tsOf(m.timestamp);
    const content = clip(m.content);
    if (!content){ rejected++; continue; }
    if (OTP_RE.test(content) || HANDLE_RE.test(content)){ rejected++; continue; }
    const isBuyer = m.sender === 'user';   // user=buyer, bot=ours
    if (isBuyer){
      const kind = m.message_type === 'clicked' ? 'button_tap' : 'free_text';
      if (kind==='button_tap') button_taps.push(content);
      // typed buyer messages that look like a product enquiry feed products_enquired
      const ne = content.match(/Need best price for\s+([^\n,]+)/i);
      if (ne) products_enquired.add(ne[1].trim());
      turns.push({ ts, sender:'buyer', kind, text:content, channel:'inbound' });
    } else {
      // bot = OURS (context). Reject footer/unsubscribe only.
      if (FOOTER_RE.test(content)){ rejected++; continue; }
      turns.push({ ts, sender:'ours', kind:'caption', text:content, channel:'inbound' });
    }
  }

  // ---------- sort by ts (nulls last, stable) ----------
  turns.forEach((t,i)=>{ t._i=i; });
  turns.sort((a,b)=>{
    const at=a.ts, bt=b.ts;
    if(at==null && bt==null) return a._i-b._i;
    if(at==null) return 1;
    if(bt==null) return -1;
    if(at!==bt) return at-bt;
