// ---- helpers (lifted VERBATIM from v9.5 isq-parser header) -----------------
const dec = s => { try { return decodeURIComponent(String(s).replace(/\+/g,' ')); } catch(e){ return String(s); } };
const isEmpty = v => v==null||v===''||v==='-'||v==='0'||v===0;
const titleCase = s => String(s).trim().toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());
const slugName = s => dec(s).replace(/\.html?$/i,'').replace(/-\d{6,}$/,'').replace(/-/g,' ').trim();
const mode = obj => Object.keys(obj).sort((a,b)=>obj[b]-obj[a])[0]||null;
const dedupeCI = arr => { const m=new Map(); for(const x of arr){ const k=String(x).toLowerCase().trim(); if(k&&!m.has(k)) m.set(k,x); } return [...m.values()]; };
const cleanUrl = u => { if(typeof u!=='string') return ''; const m=u.match(/^(?:GET|POST|PUT|DELETE|HEAD|PATCH)?\s*(\S+)/); return (m?m[1]:u).split(' HTTP')[0]; };
const qp = (url,key)=>{ const i=url.indexOf('?'); if(i<0) return null; const w=key.toLowerCase(); for(const kv of url.slice(i+1).split('&')){const eq=kv.indexOf('='); if(eq>0&&kv.slice(0,eq).toLowerCase()===w) return dec(kv.slice(eq+1));} return null; };
