function fixNull(o){ const out={}; for(const k in o){ out[k] = o[k]===undefined ? null : o[k]; } return out; }

// ---- date helpers (DD-MON-YY e.g. 18-JUN-26) -------------------------------
const MON={JAN:0,FEB:1,MAR:2,APR:3,MAY:4,JUN:5,JUL:6,AUG:7,SEP:8,OCT:9,NOV:10,DEC:11};
function parseDMY(s){ if(!s) return null; const m=String(s).trim().match(/^(\d{1,2})-([A-Za-z]{3})-(\d{2,4})$/); if(!m) return null; const d=+m[1],mo=MON[m[2].toUpperCase()],y=+m[3]; if(mo==null) return null; const yr=y<100?2000+y:y; const dt=new Date(Date.UTC(yr,mo,d)); return isNaN(dt.getTime())?null:dt; }
function daysAgo(dt){ if(!dt) return null; return Math.round((Date.now()-dt.getTime())/86400000); }

// ============================================================================
// SPEC-FLATTEN  (lifted VERBATIM in spirit from v9.5 isq-parser parseISQ inner
// loop: iterate DATA keys skipping OLD_DATA; coerce array-or-object; keep
// `${IM_SPEC_MASTER_DESC}: ${ISQ_RESPONSE}`; pull MCATID; break out
// Probable Order Value / Probable Requirement Type. Extended with the other
// owner-listed break-outs Buyer Profile / Purchase Frequency.)
// Returns empty:true when section is empty (only OLD_DATA) so caller can placeholder.
// ============================================================================
// classify a spec's PROVENANCE (for the dashboard legend: Buyer Filled / Auto-Filled / Agent Filled / Predicted).
// Reads whatever source flag the ISQ row carries; an answered ISQ with NO flag = buyer-provided (the common case).
// NOTE: confirm the real IndiaMART field name and extend the candidate list below if specs come back all 'buyer'.
function classifyFill(s){
  const raw = String(s.FILLED_BY ?? s.RESPONSE_SOURCE ?? s.ISQ_RESPONSE_TYPE ?? s.RESPONSE_TYPE ?? s.SOURCE ?? s.IS_BUYER_FILLED ?? s.FILL_TYPE ?? '').toLowerCase().trim();
  if(!raw) return 'unknown'; // v44: NO flag field on the ISQ row => provenance UNKNOWN, never fabricated as buyer-typed
  if(/agent|cce|tele|caller/.test(raw)) return 'agent';
  if(/predict|model|\bml\b|derive/.test(raw)) return 'predicted';
  if(/auto|default|system|prefill/.test(raw)) return 'auto';
  return 'unknown'; // v38: no flag ⇒ unknown, not fabricated buyer
}
function flattenISQ(it){
  const data = it && it.RESPONSE && it.RESPONSE.DATA;
  if(!data) return { specsObj:null, specsMeta:null, list:[], mcat:null, ov:null, rt:null, bp:null, pf:null, empty:true };
  const sectionKeys = Object.keys(data).filter(k=>k!=='OLD_DATA');
  if(sectionKeys.length===0) return { specsObj:null, specsMeta:null, list:[], mcat:null, ov:null, rt:null, bp:null, pf:null, empty:true };
  const specsObj={}; const specsMeta={}; const list=[]; let mcat=null, ov=null, rt=null, bp=null, pf=null;
  for(const k of sectionKeys){ let arr=data[k]; if(!Array.isArray(arr)) arr=[arr];
    for(const s of arr){ if(!s||!s.IM_SPEC_MASTER_DESC) continue; mcat=mcat||s.MCATID; const desc=s.IM_SPEC_MASTER_DESC, val=s.ISQ_RESPONSE;
