// Read the two named upstream inputs. Tolerate either named-node access (real
// n8n) OR the intern's $input.all() content-shape discrimination. Each branch
// is wrapped so a missing input never throws.
function readInputs(){
  let rfqRaw=null, isqArr=null;
  // (1) by-name access (preferred when wired by name)
  try { const r=$('rfq-details-api').first(); if(r&&r.json!=null) rfqRaw=r.json; } catch(e){}
  try { const all=$('getisq5').all(); if(all&&all.length) isqArr=all.map(i=>i.json); } catch(e){}
  // (2) fallback: discriminate $input.all() by content shape
  if(rfqRaw==null || isqArr==null){
    let items=[]; try { items=$input.all().map(i=>i.json); } catch(e){ items=[]; }
    const isqBucket=[];
    for(const j of items){ if(j==null) continue;
      const root=pickRoot(j);
      const D=root&&root.RESPONSE&&root.RESPONSE.DATA;
      if(!D) continue;
      // RFQ shape: DATA.Listing[] present
      if(rfqRaw==null && Array.isArray(D.Listing)){ rfqRaw=root; continue; }
