// safe decode: escape any lone/trailing '%' (e.g. "25%") that isn't a valid %XX escape, else decodeURIComponent throws
// and the value reaches the LLM still URL-encoded ("Copper%20Sulphate...25%").
const dec = s => { try { return decodeURIComponent(String(s).replace(/\+/g,' ').replace(/%(?![0-9A-Fa-f]{2})/g,'%25')); } catch(e){ return String(s).replace(/\+/g,' '); } };
