function omitEmpty(o){
  const out={};
  for(const k in o){ const v=o[k];
    if(v==null||v==='') continue;
    if(Array.isArray(v)){ if(v.length) out[k]=v; continue; }
    if(typeof v==='object'){ const c=omitEmpty(v); if(Object.keys(c).length) out[k]=c; continue; }
